import type { PlayerId } from '../contracts/game';
import type { Vec3 } from '../contracts/math';
import type { HazardObstacle, Hole } from '../courses/types';

export interface HazardResolution {
  playerId: PlayerId;
  resetPosition: Vec3;
  penaltyStrokes: number;
}

export class HoleSystem {
  private readonly lastSafePositions = new Map<PlayerId, Vec3>();

  constructor(private readonly maxCupCaptureSpeed = 1.5) {}

  setInitialSafePosition(playerId: PlayerId, position: Vec3): void {
    this.lastSafePositions.set(playerId, { ...position });
  }

  markSafePosition(playerId: PlayerId, position: Vec3): void {
    this.lastSafePositions.set(playerId, { ...position });
  }

  getLastSafePosition(playerId: PlayerId, fallback: Vec3): Vec3 {
    return { ...(this.lastSafePositions.get(playerId) ?? fallback) };
  }

  isBallHoled(hole: Hole, position: Vec3, speed: number): boolean {
    if (speed > this.maxCupCaptureSpeed) return false;
    const dx = position.x - hole.cup.position.x;
    const dz = position.z - hole.cup.position.z;
    const horizontalDistance = Math.hypot(dx, dz);
    const verticalDelta = position.y - hole.cup.position.y;
    return horizontalDistance <= hole.cup.radius && verticalDelta <= hole.cup.captureDepth && verticalDelta >= -hole.cup.captureDepth;
  }

  isOutsideBounds(hole: Hole, position: Vec3): boolean {
    return position.x < hole.bounds.min.x || position.x > hole.bounds.max.x ||
      position.y < hole.bounds.min.y || position.y > hole.bounds.max.y ||
      position.z < hole.bounds.min.z || position.z > hole.bounds.max.z;
  }

  resolveHazard(playerId: PlayerId, hole: Hole, hazard?: HazardObstacle): HazardResolution {
    return {
      playerId,
      resetPosition: this.getLastSafePosition(playerId, hole.spawn),
      penaltyStrokes: hazard?.penaltyStrokes ?? 1,
    };
  }
}
